import { Queue, Worker, Job } from 'bullmq';

interface JobPayload {
  userId: string;
  amount: number;
}

const connection = { host: '127.0.0.1', port: 6379 };

// Main work queue: self-schedules retries with exponential backoff.
export const workQueue = new Queue<JobPayload>('billing-jobs', {
  connection,
  defaultJobOptions: {
    attempts: 5,
    backoff: {
      type: 'exponential',
      delay: 1000,
    },
  },
});

// Separate queue that parks permanently-broken ("poison") jobs.
export const deadLetterQueue = new Queue('billing-jobs-dlq', { connection });

/**
 * Side effect attached to the job: charges the user and sends an alert.
 * NOT idempotent yet — calling it twice for the same job double-charges/
 * double-alerts.
 */
async function chargeAndAlert(payload: JobPayload): Promise<void> {
  await chargeUser(payload.userId, payload.amount);
  await sendAlert(payload.userId, `Charge of ${payload.amount} processed`);
}

const worker = new Worker<JobPayload>(
  'billing-jobs',
  async (job: Job<JobPayload>) => {
    // Real work — throws on failure so BullMQ marks this attempt failed
    // and (if attempts remain) automatically re-schedules a retry with backoff.
    await chargeAndAlert(job.data);
  },
  { connection },
);

// THE BUG: this fires on EVERY failed attempt, not only once retries
// are exhausted. It never reads job.attemptsMade and never compares it
// against job.opts.attempts, so a transient failure (fails twice, then
// succeeds) still gets dead-lettered on attempt #1 and #2 — and the
// side effect ends up re-firing every time this handler runs.
worker.on('failed', async (job, err) => {
  if (!job) return;

  await deadLetterQueue.add('dead', {
    jobId: job.id,
    data: job.data,
    reason: err.message,
  });
});

// --- stubs referenced above ---
declare function chargeUser(userId: string, amount: number): Promise<void>;
declare function sendAlert(userId: string, message: string): Promise<void>;
